open Autoform.Core Autoform.Generated.Cachetools
def lookup (cls field : String) : EResult :=
  let ctx : Ctx :=
    { dialect := program.dialect, table := program.table
    , properties := program.properties, builtinBases := program.builtinBases
    , excClasses := program.excClasses }
  (evalExpr ctx 80 [{ cls := cls, fields := [("_TimedCache__timer", .int 77)] }]
    [("receiver", .ref 0)] (.field (.name "receiver") field)).2
def main : IO Unit := do
  for (cls, field) in [("Cache", "getsizeof"), ("FIFOCache", "getsizeof"),
      ("_TimedCache", "timer"), ("TTLCache", "timer")] do
    IO.println (cls ++ "." ++ field ++ ": " ++ reprStr (lookup cls field))
